// クライアント分散コンピューティングのタスクカタログ（サーバー専用）。
// expected は正解値であり、クライアントには絶対に送らない（結果の照合にのみ使う）。
// 生成方法: 標準 perft 検証局面スイートを divide 分割（原則2手先まで展開）し、
// 各タスクの expected を lib/chess-perft.ts で算出。スイートごとの合計が公開
// 既知値と一致することを tests/compute.test.mjs が常時検証する。
//
// スイート2（公開 perft 値, chessprogramming wiki の Perft Results）:
//   startpos: depth 6 = 119,060,324 / kiwipete: depth 5 = 193,690,690
//   pos3: depth 7 = 178,633,661 / pos5: depth 5 = 89,941,194
//   pos6: depth 5 = 164,075,551
//   合計 6,195 タスク / 745,401,420 ノード（スイート1の約18倍）
// pos4 は depth 6 だけで 706,045,033 ノードとなり、合計規模の上限を超える
// うえ、divide 2 では1タスク上限（300万ノード）を守れず、divide 3 では
// タスク数上限を超えるため、スイート2には含めない（スイート1で検証済み）。

export type ComputeTaskDef = {
  id: string;
  suite: string;
  fen: string;
  depth: number;
  expected: number;
};

